import{_ as t,a,b as n}from"./chunks/orin_projection.3yQNbicu.js";import{_ as s,o,c as i,a0 as r}from"./chunks/framework.CzVS_xMp.js";const w=JSON.parse('{"title":"Week 4 Lab Results","description":"","frontmatter":{},"headers":[],"relativePath":"inference/efficient-llm-inference-systems/week04/results/RESULTS.md","filePath":"inference/efficient-llm-inference-systems/week04/results/RESULTS.md","lastUpdated":1788432796000}'),d={name:"inference/efficient-llm-inference-systems/week04/results/RESULTS.md"};function l(h,e,b,c,m,p){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="week-4-lab-results" tabindex="-1">Week 4 Lab Results <a class="header-anchor" href="#week-4-lab-results" aria-label="Permalink to &quot;Week 4 Lab Results&quot;">​</a></h1><p>Hardware: RTX 5080 16GB (Blackwell, sm_120) · cu128 PyTorch 2.11 · bitsandbytes 0.49.2 · transformers 5.12.1 Model: Qwen/Qwen2.5-3B-Instruct</p><p>The README sketches an AWQ INT4 path. On Blackwell the prebuilt AWQ kernels are unreliable, so the low-bit paths here use <strong>bitsandbytes</strong>: 8-bit (LLM.int8()) and 4-bit NF4. This substitution is the source of the most important finding below, so read Lab 1 carefully.</p><p>The headline finding in one figure — same 4-bit width, opposite speed depending on the kernel:</p><p><img src="'+t+'" alt="Same bits, opposite speed: the kernel decides"></p><h2 id="lab-1-—-quant-compare-latency-memory-32-token-generation-batch-1" tabindex="-1">Lab 1 — quant_compare (latency + memory, 32-token generation, batch 1) <a class="header-anchor" href="#lab-1-—-quant-compare-latency-memory-32-token-generation-batch-1" aria-label="Permalink to &quot;Lab 1 — quant_compare (latency + memory, 32-token generation, batch 1)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>variant</th><th>ms/gen</th><th>peak mem</th><th>speedup vs BF16</th></tr></thead><tbody><tr><td>BF16</td><td>380.4</td><td>5.76 GB</td><td>1.00x</td></tr><tr><td>INT8 (bnb)</td><td>1880.9</td><td>3.25 GB</td><td><strong>0.20x (5x slower)</strong></td></tr><tr><td>NF4 (bnb)</td><td>660.6</td><td>1.98 GB</td><td><strong>0.58x (1.7x slower)</strong></td></tr></tbody></table><p><strong>Memory matches the README prediction</strong> (BF16→INT8→INT4 roughly halving and quartering). <strong>Latency does not</strong> — both quantized variants are <em>slower</em> than BF16, the opposite of the README&#39;s &quot;INT4 40-70% faster&quot; expectation. This is a real and expected result, not a bug:</p><ul><li>The README&#39;s speedup assumed <strong>AWQ&#39;s fused INT4 GEMM kernels</strong>. bitsandbytes is optimized for <em>memory</em> (QLoRA training), not decode latency.</li><li><strong>INT8 / LLM.int8()</strong> does mixed-precision outlier decomposition (an FP16 path for outlier channels) on every matmul. At batch=1 this overhead dominates.</li><li><strong>NF4</strong> dequantizes back to BF16 per matmul; the dequant cost is not hidden.</li><li>On RTX 5080 the 3B model already fits with bandwidth to spare, so the bandwidth <em>saving</em> from fewer weight bytes is small relative to the dequant <em>overhead</em>. The Week 2 &quot;decode is bandwidth-bound&quot; claim still holds — but the saving only turns into speed when the kernel is bandwidth-optimized (AWQ / Marlin / native FP4), which bnb is not.</li></ul><p><strong>Lesson: kernel quality matters as much as bit-width.</strong> Fewer bits guarantees less memory; it only guarantees less latency with a fused low-bit kernel.</p><p><img src="'+a+'" alt="bitsandbytes: memory drops, latency rises"></p><h2 id="lab-1b-—-vllm-quant-bench-fused-int4-on-blackwell-batch-1-32-token-gen" tabindex="-1">Lab 1b — vllm_quant_bench (fused INT4 on Blackwell, batch 1, 32-token gen) <a class="header-anchor" href="#lab-1b-—-vllm-quant-bench-fused-int4-on-blackwell-batch-1-32-token-gen" aria-label="Permalink to &quot;Lab 1b — vllm_quant_bench (fused INT4 on Blackwell, batch 1, 32-token gen)&quot;">​</a></h2><p>vLLM 0.23.0 · torch 2.11+cu130 · Triton attention backend (FlashInfer misdetects sm_120, so <code>VLLM_ATTENTION_BACKEND=TRITON_ATTN</code>).</p><table tabindex="0"><thead><tr><th>variant</th><th>ms/gen</th><th>tok/s</th><th>speedup vs BF16</th></tr></thead><tbody><tr><td>BF16</td><td>258.6</td><td>123.7</td><td>1.00x</td></tr><tr><td>AWQ-INT4 (awq_marlin)</td><td>121.0</td><td>264.5</td><td><strong>2.14x faster</strong></td></tr></tbody></table><p><strong>This is the result Lab 1 was missing.</strong> Same model, same batch=1 / 32-token decode, but a <em>fused</em> INT4 path (AWQ + Marlin) instead of bitsandbytes:</p><ul><li>AWQ-INT4 is <strong>2.14x faster</strong> than BF16 — exceeding the README&#39;s &quot;40-70% faster&quot; expectation (which assumed exactly this AWQ kernel).</li><li>Contrast with Lab 1 bnb on the same GPU: INT8 was 5x <em>slower</em>, NF4 1.7x <em>slower</em>. Same bit-widths, opposite outcome — the kernel is the difference.</li><li>Even the BF16 baseline is faster here (259 ms) than HF <code>generate</code> in Lab 1 (380 ms), because vLLM adds CUDA graphs + paged attention. The fair apples-to-apples comparison is within each engine; across both engines the ordering is what matters: <strong>fused low-bit kernel → real decode speedup; bnb → memory win only.</strong></li></ul><p>Takeaway confirmed empirically: on RTX 5080 the README&#39;s decode speedup is reproducible, but only via a Blackwell-capable fused INT4 path (AWQ/Marlin in vLLM), not via bitsandbytes.</p><h2 id="lab-2-—-perplexity-eval-wikitext-2-100-samples" tabindex="-1">Lab 2 — perplexity_eval (WikiText-2, 100 samples) <a class="header-anchor" href="#lab-2-—-perplexity-eval-wikitext-2-100-samples" aria-label="Permalink to &quot;Lab 2 — perplexity_eval (WikiText-2, 100 samples)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>variant</th><th>perplexity</th><th>Δ vs BF16</th></tr></thead><tbody><tr><td>BF16</td><td>11.942</td><td>—</td></tr><tr><td>INT8 (bnb)</td><td>12.017</td><td>+0.63%</td></tr><tr><td>NF4 (bnb)</td><td>12.898</td><td><strong>+8.00%</strong></td></tr></tbody></table><ul><li>INT8 is <strong>near-lossless</strong> (+0.63%), matching the README&#39;s &quot;INT8 ~99%&quot; claim.</li><li>NF4 exceeds the README&#39;s <strong>5% production-viability threshold</strong> (+8%). For 4-bit on a 3B model, weight-only quantization without AWQ-style salient-channel protection visibly costs quality — consistent with the README note that smaller models (≤7B) need the better PTQ algorithms.</li></ul><h2 id="lab-3-—-orin-quant-projection-bandwidth-bound-model-no-gpu" tabindex="-1">Lab 3 — orin_quant_projection (bandwidth-bound model, no GPU) <a class="header-anchor" href="#lab-3-—-orin-quant-projection-bandwidth-bound-model-no-gpu" aria-label="Permalink to &quot;Lab 3 — orin_quant_projection (bandwidth-bound model, no GPU)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>precision</th><th>weight</th><th>ms/token</th><th>16-tok decode</th><th>speedup</th></tr></thead><tbody><tr><td>BF16</td><td>14 GB</td><td>94</td><td>1.50 s</td><td>1.0x</td></tr><tr><td>INT8</td><td>7 GB</td><td>47</td><td>0.75 s</td><td>2.0x</td></tr><tr><td>INT4</td><td>3.5 GB</td><td>23.5</td><td>0.38 s</td><td>4.0x</td></tr></tbody></table><p><img src="'+n+'" alt="Orin edge projection: weight bytes to decode latency"></p><p>Calibration scale (measured/theoretical) = 1.34; the BF16 row reproduces the Week 3 measurement exactly. INT4 projects a 4x decode speedup <em>on Orin</em>, where the model is genuinely bandwidth-bound and memory-constrained — the regime where quantization pays off, unlike the desktop RTX 5080 in Lab 1.</p><h2 id="takeaway" tabindex="-1">Takeaway <a class="header-anchor" href="#takeaway" aria-label="Permalink to &quot;Takeaway&quot;">​</a></h2><p>The two latency results tell opposite stories on purpose:</p><ul><li><strong>Lab 1 (RTX 5080, bnb):</strong> model fits, fast bandwidth, no fused kernel → quantization saves memory but <em>costs</em> latency.</li><li><strong>Lab 3 (Orin, projected):</strong> model bandwidth-bound and memory-tight → quantization is the difference between feasible and not, and 4x faster decode.</li></ul><p>Quantization choice is hardware- and kernel-dependent, not just a bit count. This is now confirmed both ways on the same RTX 5080: bitsandbytes INT8/NF4 are <em>slower</em> than BF16 (Lab 1), while AWQ-INT4 via vLLM&#39;s Marlin kernel is <strong>2.14x faster</strong> (Lab 1b). The README&#39;s decode speedup is real — it just requires a Blackwell-capable fused low-bit kernel, not bitsandbytes.</p>',28)])])}const y=s(d,[["render",l]]);export{w as __pageData,y as default};
